-- name: AddCase :one
-- The reference is generated by the column default (CASE-2026-000042).
SELECT * FROM compliance_ext.add_case(
    sqlc.narg(summary)
);

-- name: GetCase :one
SELECT id, reference, status, assignee_nk, summary, closed_at, created_at, updated_at
FROM compliance_ext.cases
WHERE id = sqlc.arg(id)::uuid;

-- name: ListCases :many
-- The status filter is optional: a NULL value disables it.
SELECT id, reference, status, assignee_nk, summary, closed_at, created_at, updated_at
FROM compliance_ext.cases
WHERE (sqlc.narg(status)::compliance_case_status IS NULL OR status = sqlc.narg(status)::compliance_case_status)
ORDER BY created_at DESC
LIMIT sqlc.arg(max_rows);

-- name: UpdateCase :one
-- Partial update; zero rows = unknown or soft-deleted id.
SELECT * FROM compliance_ext.update_case(
    sqlc.arg(id)::uuid,
    sqlc.narg(status)::compliance_case_status,
    sqlc.narg(assignee_nk)::uuid,
    sqlc.narg(summary)
);

-- name: AddCaseAlert :one
-- Idempotent link: a repeated call returns the existing row.
SELECT * FROM compliance_ext.add_case_alert(
    sqlc.arg(case_id)::uuid,
    sqlc.arg(alert_id)::uuid
);
